<template><div class="space-y-4"><el-input v-model="input" type="textarea" :rows="12" placeholder="粘贴 XML 内容"/><div class="flex gap-2"><el-button type="primary" size="small" @click="format">格式化</el-button><el-button size="small" @click="compress">压缩</el-button></div><el-input v-if="output" v-model="output" type="textarea" :rows="12" readonly/></div></template>
<script setup lang="ts">import { ref } from 'vue';import { ElMessage } from 'element-plus';const input=ref('');const output=ref('');const format=()=>{try{let s=input.value.replace(/>\s*</g,'><'),level=0;output.value=s.replace(/(>)(<)(\/?)/g,'$1\n$2$3').split('\n').map(line=>{if(line.match(/<\//))level--;const r='  '.repeat(Math.max(level,0))+line;if(line.match(/<[^!?][^>]*[^/]>/)&&!line.includes('</'))level++;return r}).join('\n')}catch{ElMessage.error('XML 格式错误')}};const compress=()=>{output.value=input.value.replace(/>\s*</g,'><').trim()}</script>
